      (other is ProjectGeofence &&
          other.projectId == this.projectId &&
          other.centerLat == this.centerLat &&
          other.centerLng == this.centerLng &&
          other.radiusMeters == this.radiusMeters &&
          other.updatedAt == this.updatedAt);
}

