  final String leadId;

  /// call | visit | meeting | whatsapp | note | stage
  final String kind;
  final String note;
  final String byUser;
  final DateTime createdAt;
  const CrmActivity({
    required this.id,
    required this.companyId,
    required this.leadId,
    required this.kind,
    required this.note,
    required this.byUser,
    required this.createdAt,
  });
