class Tool extends DataClass implements Insertable<Tool> {
  final String id;
  final String companyId;
  final String name;

  /// Asset tag painted on it.
  final String? code;
  final String? category;
  final double? value;
  final String? storeId;

  /// in_use (normal) | repair | retired. Issued and lost come from issues.
  final String condition;
  final String? notes;
  final String createdBy;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Tool({
    required this.id,
    required this.companyId,
    required this.name,
    this.code,
    this.category,
    this.value,
    this.storeId,
    required this.condition,
    this.notes,
    required this.createdBy,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['company_id'] = Variable<String>(companyId);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || code != null) {
      map['code'] = Variable<String>(code);
    }
    if (!nullToAbsent || category != null) {
      map['category'] = Variable<String>(category);
    }
    if (!nullToAbsent || value != null) {
      map['value'] = Variable<double>(value);
    }
    if (!nullToAbsent || storeId != null) {
      map['store_id'] = Variable<String>(storeId);
    }
    map['condition'] = Variable<String>(condition);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_by'] = Variable<String>(createdBy);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ToolsCompanion toCompanion(bool nullToAbsent) {
    return ToolsCompanion(
      id: Value(id),
      companyId: Value(companyId),
      name: Value(name),
      code: code == null && nullToAbsent ? const Value.absent() : Value(code),
      category: category == null && nullToAbsent
          ? const Value.absent()
          : Value(category),
      value: value == null && nullToAbsent
          ? const Value.absent()
          : Value(value),
      storeId: storeId == null && nullToAbsent
          ? const Value.absent()
          : Value(storeId),
      condition: Value(condition),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      createdBy: Value(createdBy),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Tool.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Tool(
      id: serializer.fromJson<String>(json['id']),
      companyId: serializer.fromJson<String>(json['companyId']),
      name: serializer.fromJson<String>(json['name']),
      code: serializer.fromJson<String?>(json['code']),
      category: serializer.fromJson<String?>(json['category']),
      value: serializer.fromJson<double?>(json['value']),
      storeId: serializer.fromJson<String?>(json['storeId']),
      condition: serializer.fromJson<String>(json['condition']),
      notes: serializer.fromJson<String?>(json['notes']),
      createdBy: serializer.fromJson<String>(json['createdBy']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'companyId': serializer.toJson<String>(companyId),
      'name': serializer.toJson<String>(name),
      'code': serializer.toJson<String?>(code),
      'category': serializer.toJson<String?>(category),
      'value': serializer.toJson<double?>(value),
      'storeId': serializer.toJson<String?>(storeId),
      'condition': serializer.toJson<String>(condition),
      'notes': serializer.toJson<String?>(notes),
      'createdBy': serializer.toJson<String>(createdBy),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
