          other.companyId == this.companyId &&
          other.name == this.name &&
          other.code == this.code &&
          other.category == this.category &&
          other.value == this.value &&
          other.storeId == this.storeId &&
          other.condition == this.condition &&
          other.notes == this.notes &&
